function Counter() {
  const [count, setCount] = React.useState(0);
  return (
    <div>
      <h1>Counter</h1>
      <p>Count: {count}</p>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<Counter />);

function Counter() {
  const [count, setCount] = React.useState(0);
  return (
    <div>
      <h1>Counter</h1>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>+</button>
      <button onClick={() => setCount(count - 1)}>-</button>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<Counter />);

function Counter() {
  const [count, setCount] = React.useState(0);
  return (
    <div>
      <h1>Counter</h1>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>+</button>
      <button onClick={() => count > 0 && setCount(count - 1)}>-</button>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<Counter />);
